package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.controller.jobs.JobsController;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

/** Actual durable report-result discard; unused read and identity ports are explicit fixtures. */
@EnabledIfEnvironmentVariable(named="B44_MYSQL",matches="true")
class OwnerJobDiscardResultHttpMySqlTest {
    OwnerJobDiscardResultMySqlTest f;MockMvc mvc;IdentityService auth;
    @BeforeEach @SuppressWarnings("unchecked") void setup(){f=new OwnerJobDiscardResultMySqlTest();f.setup();auth=mock(IdentityService.class);when(auth.authenticate("fictional-session")).thenReturn(f.owner);when(auth.authorizeWrite("fictional-session","fictional-csrf","https://site.example.invalid")).thenReturn(f.owner);ObjectProvider<IdentityService> identity=mock(ObjectProvider.class);when(identity.getIfAvailable()).thenReturn(auth);ObjectProvider<JobsService> jobs=mock(ObjectProvider.class);var cancel=new OwnerJobCancelService(f.f.writes,new JdbcOwnerJobCancellation(f.f.source),f.f.clock);when(jobs.getIfAvailable()).thenReturn(new OwnerJobsService(mock(OwnerJobsReadService.class),new OwnerJobCommandsService(cancel,null,null,f.service)));mvc=MockMvcBuilders.standaloneSetup(new JobsController(identity,jobs)).build();}
    jakarta.servlet.http.Cookie cookie(){return new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session");}
    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder action(String root,long revision,String key){return post("/admin/jobs/"+root+"/actions").cookie(cookie()).header("X-CSRF-Token","fictional-csrf").header("Origin","https://site.example.invalid").header("Idempotency-Key",key).contentType("application/json").content("{\"expected_revision\":"+revision+",\"action\":\"discard_result\",\"reason\":\"Fictional retained result abandonment\"}");}
    @Test void originalDiscardHttpEffectReplaysAfterRevisionChangeWithoutAnyResultBody()throws Exception{var first=mvc.perform(action(ResultJdbcStoreTest.ROOT,f.revision,"fictional-http-discard!")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.result_resource_ref.id").value(ResultJdbcStoreTest.ROOT)).andExpect(jsonPath("$.data.result_revision").value(f.revision+1)).andReturn();f.f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",ResultJdbcStoreTest.ROOT);var replay=mvc.perform(action(ResultJdbcStoreTest.ROOT,f.revision,"fictional-http-discard!")).andExpect(status().isOk()).andReturn();var mapper=tools.jackson.databind.json.JsonMapper.shared();assertEquals(mapper.readTree(first.getResponse().getContentAsString()).get("data"),mapper.readTree(replay.getResponse().getContentAsString()).get("data"));assertFalse(first.getResponse().getContentAsString().contains("Fictional text"));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_discard_result'",Integer.class));assertEquals(1,new JdbcJobRecords(f.f.source).byId(ResultJdbcStoreTest.ROOT).callCount());}
    @Test void absentStaleAndUnknownRootHaveFixedErrors()throws Exception{mvc.perform(action("fictional-absent",0,"fictional-absent")).andExpect(status().isNotFound()).andExpect(jsonPath("$.error.code").value("not_found"));mvc.perform(action(ResultJdbcStoreTest.ROOT,f.revision+1,"fictional-stale")).andExpect(status().isConflict()).andExpect(jsonPath("$.error.code").value("revision_conflict"));f.f.jdbc.update("UPDATE jobs SET state='unknown_external' WHERE id=?",ResultJdbcStoreTest.ROOT);mvc.perform(action(ResultJdbcStoreTest.ROOT,f.revision,"fictional-unknown")).andExpect(status().isConflict()).andExpect(jsonPath("$.error.code").value("run_frozen"));assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_discard_result'",Integer.class));}
    @Test void authCsrfUnexpectedBranchAndSqlFailureRefuse()throws Exception{mvc.perform(action(ResultJdbcStoreTest.ROOT,f.revision,"fictional-invalid").content("{\"expected_revision\":"+f.revision+",\"action\":\"discard_result\",\"reason\":\"Fictional wrong branch\",\"result_hash\":\""+"a".repeat(64)+"\"}")).andExpect(status().isBadRequest());f.f.jdbc.execute("DROP TABLE jobs");mvc.perform(post("/admin/jobs/fictional-root/actions").contentType("application/json").content("{}")).andExpect(status().isUnauthorized());when(auth.authenticate("fictional-session")).thenReturn(new IdentityService.Actor("fictional-member","member"));mvc.perform(action(ResultJdbcStoreTest.ROOT,f.revision,"fictional-role")).andExpect(status().isForbidden());when(auth.authenticate("fictional-session")).thenReturn(f.owner);mvc.perform(post("/admin/jobs/fictional-root/actions").cookie(cookie()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(action(ResultJdbcStoreTest.ROOT,f.revision,"fictional-sql")).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1")).andExpect(jsonPath("$.error.code").value("temporarily_unavailable"));}
}
